// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint88 domainHint) public {
        vm.assume(domainHint != 0);
        address player = address(uint160(domainHint));
        vm.deal(player, 10 ether);
        vm.startPrank(player);
        c.play{value: 10}();
        vm.stopPrank();
        uint256 pot = c.pot();
        uint256 balance = address(c).balance;
        assertTrue(balance == pot || balance == pot + 1);
    }
}
